In C:
if (condition1) {
    if (condition2) {
        /* both true */
    } else {
        /* condition1 true, condition2 false */
    }
} else {
    /* condition1 false */
}
A nested if places another selection inside a branch. Braces eliminate ambiguity about which if an else belongs to.

Exact program: int z=1; while(z<=5) {if(z==3){z++;} printf("%d ",z); z++;}
Trace: z=1 prints 1; z=2 prints 2; z=3 increments to 4, prints 4; z=5 prints 5; z becomes 6 and loop exits.
Output: 1 2 4 5

Leap year iff divisible by 400 OR divisible by 4 but not by 100. Complete C program:
#include <stdio.h>
int main(void) {
  int year;
  if (scanf("%d", &year) != 1) return 1;
  const char *result = (year%400==0 || (year%4==0 && year%100!=0)) ? "Leap year" : "Not a leap year";
  puts(result);
  return 0;
}
Examples: 2000 leap, 1900 not leap, 2024 leap.

An array stores homogeneous elements contiguously, supports O(1) indexed access, and is useful for tabular/sequence data. Program:
#include <stdio.h>
int sum(const int a[], size_t n) {
  int result=0;
  for(size_t i=0;i<n;i++) result+=a[i];
  return result;
}
int main(void) {
  int a[2];
  if(scanf("%d%d",&a[0],&a[1])!=2)return 1;
  printf("Sum = %d\n",sum(a,2));
  return 0;
}
The function receives a pointer to the array's first element; n carries its length.

Searching locates an item or reports absence. Linear search checks items from start to end, works with unsorted arrays, and costs O(n) worst case (O(1) best). Complete program:
#include <stdio.h>
int linear_search(const int a[], int n, int target) {
  for(int i=0;i<n;i++) if(a[i]==target) return i;
  return -1;
}
int main(void){
  int a[100],n,target;
  if(scanf("%d",&n)!=1||n<1||n>100)return 1;
  for(int i=0;i<n;i++)if(scanf("%d",&a[i])!=1)return 1;
  if(scanf("%d",&target)!=1)return 1;
  int pos=linear_search(a,n,target);
  if(pos<0) puts("Not found");
  else printf("Found at index %d\n",pos);
  return 0;
}

#include <stdio.h>
int main(void) {
  int a,b,c,d;
  if(scanf("%d%d%d%d",&a,&b,&c,&d)!=4)return 1;
  int max=a;
  if(b>max)max=b;
  if(c>max)max=c;
  if(d>max)max=d;
  printf("Largest = %d\n",max);
  return 0;
}
Four constant-time comparisons/updates: O(1) time and space.

The figure has a centered apex, two boundary stars on each inner row, and a solid base. Print a general hollow isosceles pyramid of height n:
#include <stdio.h>
int main(void) {
  int n=5;
  for(int row=1;row<=n;row++) {
    for(int s=0;s<n-row;s++)putchar(' ');
    for(int col=1;col<=2*row-1;col++) {
      if(row==n||col==1||col==2*row-1)putchar('*');
      else putchar(' ');
    }
    putchar('\n');
  }
  return 0;
}
Output for n=5:
    *
   * *
  *   *
 *     *
*********
Increase n to match the dimensions of the printed figure exactly.

#include <stdio.h>
#define MAX 20
int main(void) {
  int n,a[MAX][MAX],b[MAX][MAX],c[MAX][MAX]={0};
  if(scanf("%d",&n)!=1||n<1||n>MAX)return 1;
  for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(scanf("%d",&a[i][j])!=1)return 1;
  for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(scanf("%d",&b[i][j])!=1)return 1;
  for(int i=0;i<n;i++)for(int j=0;j<n;j++)for(int k=0;k<n;k++)c[i][j]+=a[i][k]*b[k][j];
  for(int i=0;i<n;i++){for(int j=0;j<n;j++)printf("%d ",c[i][j]);putchar('\n');}
  return 0;
}
Formula C[i][j]=Σ(k=0..n−1) A[i][k]×B[k][j]. Classical runtime Θ(n³), auxiliary result Θ(n²).

Bubble sort compares adjacent elements and swaps out-of-order ones. After successive passes, largest remaining value moves to the end. Sorted output: 2,3,4,5,6,7,8,9.
Complete C:
#include <stdio.h>
int main(void){
  int a[]={7,3,8,5,9,2,4,6};int n=8;
  for(int i=0;i<n-1;i++){
    int swapped=0;
    for(int j=0;j<n-i-1;j++)if(a[j]>a[j+1]){
      int t=a[j];a[j]=a[j+1];a[j+1]=t;swapped=1;
    }
    if(!swapped)break;
  }
  for(int i=0;i<n;i++)printf("%d ",a[i]);
  return 0;
}
Bubble sort: best Θ(n) with swap flag; average/worst Θ(n²). Insertion sort: best Θ(n) on sorted input, average/worst Θ(n²), often fewer swaps and good on nearly sorted data. Both use Θ(1) extra space and are stable with strict comparison.

C formally passes all arguments by value; passing pointer values provides reference-like access to caller objects. Use pointer parameters to modify originals:
#include <stdio.h>
void swap(int *a,int *b){int t=*a;*a=*b;*b=t;}
int main(void){
  int x=10,y=20;
  swap(&x,&y);
  printf("x=%d y=%d\n",x,y);
  return 0;
}
Output: x=20 y=10. The caller supplies addresses with &; the function dereferences them with *.

Dynamic memory allocation (DMA here, not Direct Memory Access) obtains storage from the heap at runtime with malloc/calloc/realloc, released by free. Complete program:
#include <stdio.h>
#include <stdlib.h>
int main(void){
  size_t n; long long sum=0;
  if(scanf("%zu",&n)!=1||n==0||n>1000000)return 1;
  if(n>SIZE_MAX/sizeof(int))return 1;
  int *a=malloc(n*sizeof *a);
  if(!a){perror("malloc");return 1;}
  for(size_t i=0;i<n;i++){
    if(scanf("%d",&a[i])!=1){free(a);return 1;}
    sum+=a[i];
  }
  printf("Sum = %lld\n",sum);
  free(a);return 0;
}
Add #include <stdint.h> to make SIZE_MAX available in portable C99/C11. Alternatively omit the overflow check when n is already bounded. The program validates allocation and frees memory.

A pointer is a typed variable holding the memory address of another object/function. Example: int x=5; int *p=&x; printf("%d",*p); displays 5. Self-referential structures contain pointers to another instance of their own type, enabling linked lists and trees:
struct Node { int data; struct Node *next; };
struct Node a={10,NULL},b={20,NULL};
a.next=&b;
Traversal: for(struct Node *p=&a;p;p=p->next)printf("%d ",p->data); // 10 20
The pointer is to the same *structure type*, not a structure embedded by value (which would have infinite size).
